var areaC = function(l){
  const a = l**2;
  return a;
}

var areaCirculo = r => {
  const a =Math.PI*r**2;
  return a;
}

var alcance = (O, v, g) =>{
  const x = v**2 * Math.sin(2*O)/g;
  return x;
}

var masa = (V, P, T) =>{
  const M = 16.04;
  const R = 0.082057;
  const n = P*V/(R*T);
  const m = n*M;
  return m;
}

var ec_1 = function(x){
  const b = x**3 + 2;
  const a = 3 + b/5;
  const c = Math.sqrt(a);
  const d = Math.log(c);
  const r = (a+b+c+d)/4;
  return r;
}
